import {createServer as createViteServer} from 'vite';
import {mkdtemp,rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {join} from 'node:path';

// Node runs test files concurrently. Vite's default shared cache can be
// regenerated by another server mid-read, including a running dev preview.
export async function createServer(options){
 const cacheDir=await mkdtemp(join(tmpdir(),'nightjar-test-vite-'));
 try{
  const server=await createViteServer({...options,cacheDir});
  const close=server.close.bind(server);
  server.close=async()=>{try{await close()}finally{await rm(cacheDir,{recursive:true,force:true,maxRetries:3,retryDelay:50})}};
  return server;
 }catch(error){await rm(cacheDir,{recursive:true,force:true,maxRetries:3,retryDelay:50});throw error}
}
